/* In-game "What's new" log. Newest first. `at` is the release time (Pacific). */
window.HW_DATA.support = { url: 'https://www.paypal.com/qrcodes/managed/a66a32a4-6956-4fd4-bc36-2160ab957433', qr: 'support-qr.png?v=2' };
