window.HW_DATA.updates = [
  { v: '0.101', at: '2026-10-29 20:30', notes: ['If you skip the tutorial, a big “Tutorial is off” button now sits on the left under your goal card. Tap it any time to turn the tutorial back on; it picks up where you left off.'] },
  { v: '0.100.1', at: '2026-10-29 20:05', backend: true, notes: ['The welcome greeter can now be Aaron, with red hair, a red beard and a middle-aged smile.'] },
  { v: '0.100', at: '2026-10-29 19:50', notes: ['New players get a proper welcome. A friendly, folksy farmer (a different one each time) greets you up close, explains the Online and Private farms (and that an online farm can be made private any time), the basics of farming from tilling to selling and unlocking stations, and then asks if you want the tutorial on or off. The tutorial can be started or stopped whenever you like.'] },
  { v: '0.99.4', at: '2026-10-29 15:40', notes: ['If Repeat is switched off for all stations, or paused on one station, that station’s recipe now says so right under the Repeat switch, with a button to turn it back on. Before, it could look like Repeat was on but nothing was happening.'] },
  { v: '0.99.3', at: '2026-10-29 15:00', notes: ['Tapping the Storage counter at the top now opens your storage on “Main storage”, so you can see exactly which goods are filling it (the 1,036 of 8,620 number). The Where buttons still switch to the Silo, Cold Cellar, Material Yard or All.'] },
  { v: '0.99.2', at: '2026-10-29 14:10', notes: ['Chairs can now turn all four ways, so they can sit properly around a table. Tap a placed chair, then Turn (or press R) to go round: each press turns it a quarter.'] },
  { v: '0.99.1', at: '2026-10-29 13:30', notes: ['A Trophy Case for your room! As soon as you have a Weekly Challenge medal, a Valley Monument model or a fish trophy, a Trophy Case is waiting inside your house. Place it like any furniture, then tap it and press Open the case: pick a medal, model or trophy and tap the spot on a shelf where you want it. Tap a piece on a shelf to move it (onto another piece to swap them) or take it out. Anything already in your trophy case is still there. A bigger house outside still gives more spots: Cottage 3, House 5, Farmhouse 8, Manor 12.'] },
  { v: '0.99', at: '2026-10-29 12:30', notes: ['Weekly challenge: a new leader track shows this week’s #1 score above yours while you play, so you can see how close you are. Your bar fills toward it, and the line under it says how many points you still need (or that you’re ahead). If you’re already #1, it shows #2 as the score to stay ahead of. The time left is in the header. On phones the side meter has a blue column for the leader; tap it for the numbers.'] },
  { v: '0.98', at: '2026-10-29 12:00', notes: ['Go inside your house! Select your house → Go inside to decorate a room of your own. Pick a piece, then tap a lit spot to place it: chairs, tables, bookshelves and rugs on the floor (furniture can stand on rugs), vases, lamps and jewel boxes on the floor or on a table, and paintings and curtains on the walls. Windows are free to add and show the real season, weather and time of day outside. Tap a placed piece to move it, turn it or put it away. Change the walls and floor under Walls & floor. Every house starts with a 4×4 room; Bigger room grows it inside, up to 9×9, without changing the house outside (the big sizes are a late-game goal). Decor you already had on display is waiting inside for you to place; Place them for me does it in one tap. The game pauses while you are inside (Settings → Pausing to change that).'] },
  { v: '0.97', at: '2026-10-29 10:30', notes: ['Some goods were kept in the wrong store. Flour and malt now go in the Silo with the grain, and finished crafts that are not food (Dyed Cloth, Clay Pots, Baskets, Iron Tools, Glass Jars, Stained Glass, Gem Rings and Necklaces, Blankets) now go in the Material Yard. The Cold Cellar keeps eggs, milk and all your food and drink. Goods you already own move to the right store by themselves, so your Cold Cellar has more room.'] },
  { v: '0.96', at: '2026-10-29 10:00', notes: ['When you stop turning the map, it now glides to the nearest straight view, so big buildings like your house and the monuments line up with the grid again (they are flat pictures drawn for the four straight views, so they looked off at in-between angles). Settings has a new Graphics section: a switch for this (Snap rotation to straight views, on by default) with the building names, player counters and market ticker switches moved in beside it.'] },
  { v: '0.95', at: '2026-10-29 09:30', notes: ['Silos, Cold Cellars and Material Yards can now be expanded eight times instead of four. The new last four are mega expansions that add twice as much space each (a fully expanded Cold Cellar now holds 1,640, up from 680; Silos and Material Yards hold 2,050, up from 850). They cost more each time, so they are a late-game goal.'] },
  { v: '0.94', at: '2026-10-29 09:00', notes: ['You can now see what is inside your Silos, Cold Cellars and Material Yards. Select one of these buildings to see the goods it holds, and in Storage a new “Where” row lets you view everything, one store at a time, or just what is in main storage.'] },
  { v: '0.93.3', backend: true, at: '2026-10-28 15:10', notes: ['Automatic error reports.'] },
  { v: '0.93.2', at: '2026-10-28 14:50', notes: ['Fixed a freeze: if a job was lined up on a tile that had since been reshaped (a tree tile turned into something else, say), the whole game could lock up and the Menu stopped opening. The job is now simply dropped, and if anything else ever goes wrong the game keeps running and the Menu still works so you can back up your farm.'] },
  { v: '0.93.1', backend: true, at: '2026-10-28 11:30', notes: ['Server score checks and an itch.io package.'] },
  { v: '0.93', at: '2026-10-28 11:30', notes: ['The Auto repeat list now looks and works like the farmhand’s jobs list: one card with a Running switch, each station on its own row with pause/resume and × buttons, and Remove all. The Open Market also has a search box on the Buy, Sell and Stations tabs, so you can find an item by typing part of its name.'] },
  { v: '0.92', at: '2026-10-28 10:20', notes: ['In the Auto repeat list, each station now has a × to take it off Repeat, and “Remove all” (tap twice) clears the list, like the farmhand’s jobs list.'] },
  { v: '0.91.2', backend: true, at: '2026-10-28 10:20', notes: ['Show your support now uses the PayPal QR code and link instead of Ko-fi.'] },
  { v: '0.91.1', backend: true, at: '2026-10-28 10:05', notes: ['Wall of Thanks: Joel is now listed as Joel K.'] },
  { v: '0.91', at: '2026-10-28 10:15', notes: ['New Wall of Thanks in the Menu (under Show your support) says thank you to the people who have supported Harvest Valley.'] },
  { v: '0.90', at: '2026-10-27 18:40', notes: ['In winter and on snow days, farm plots you can still till now show as dark frozen earth with a little frost on top, so they stand out from the plain snow tiles. Repeat counts on stations are now Forever, 1, 5, 10, 25, 100, 250, 500 or 1000 times (a count you’d already set stays as it was).'] },
  { v: '0.89', at: '2026-10-27 10:10', notes: ['The Valley Monument’s daily allowance now resets at 2 AM Pacific instead of 5 PM, so you can give again first thing in the morning. Builder’s day follows the same clock, and the countdown on the monument shows the time left. Gifts you made yesterday evening count toward yesterday, so your allowance is fresh again now.'] },
  { v: '0.88', at: '2026-10-26 21:20', notes: ['The side panel (Open Market, stations, plots and the rest) now keeps its title and × close button pinned at the top while the list under it scrolls. On phones the title sits just under the “More” bar.'] },
  { v: '0.87', at: '2026-10-26 20:50', notes: ['New gear button between Storage and Menu opens Settings in one tap. Also, every menu and panel that scrolls now keeps its title bar and × close button pinned at the top, so you never have to scroll back up to close it.'] },
  { v: '0.86.1', backend: true, at: '2026-10-26 20:45', notes: ['The tab icon (favicon) now sits in the page head so Chrome shows it.'] },
  { v: '0.86', at: '2026-10-26 13:00', notes: ['The tutorial can now be turned back on any time. If you skipped it or started without it, open Menu → Game and press “Turn the tutorial back on”: it carries on from the first step you haven’t done yet instead of starting over.'] },
  { v: '0.85', at: '2026-10-26 12:00', notes: ['If you’re showing a temporary made-up name on the leaderboard, the Leaderboard now tells you so and has a “Your player name” box right there, so you can lock in a name you like. The box starts empty instead of “Farmer”.'] },
  { v: '0.84', at: '2026-10-26 11:00', notes: ['New Auto repeat control at the bottom of the screen, right of the farmhand buttons (once Repeat Recipes is unlocked). The On/Off button pauses or resumes every station on Repeat at once, and Stations opens a list of every station that is on Repeat, each with its own On/Paused switch, so you can keep ingredients for something else without losing your Repeat settings.'] },
  { v: '0.83', at: '2026-10-26 10:30', notes: ['Weekly challenge: a warning flashes in the middle of the screen for 2 seconds when 1 minute is left, and again at 30 seconds, so the end never sneaks up on you. Also, farmers who haven’t picked a name now show up on the leaderboards with a made-up name like claire3 instead of “Farmer”, and players who hide their name get one too instead of “A farmer”.'] },
  { v: '0.82', at: '2026-10-26 10:00', notes: ['Grand orders now come up at most 4 times a day, so the Order Board is easier to keep up with. It counts new orders, so passing one doesn’t bring the next sooner, and the board tells you when the next one comes. The daily count restarts at midnight UTC (5 PM Pacific). Orders already on your board stay.'] },
  { v: '0.81', at: '2026-10-25 21:50', notes: ['Fixed the Open Market list squashing when you pressed a ×1 or ×5 button: Cancel is now a small red × the same size as the button it replaces, so the item names stay readable.'] },
  { v: '0.80', at: '2026-10-25 21:30', notes: ['Daily Puzzle: a wrong guess now costs 2% of the gold you have. Read the clue (or buy a hint) before you hand something in. Three or more wrong guesses still lower the day’s bonus too.'] },
  { v: '0.79', at: '2026-10-25 21:00', notes: ['Every house now has a Trophy Case, separate from the decor spots, for your Weekly Challenge medals, Valley Monument models and fish trophies. Select your house → Trophy case to put them in or take them out. It starts with 3 spots and grows with the house (5, 8, then 12). Medals and models can still stand on the grass too, but each one can only be in one place on a farm. Fish trophies now go in the case instead of the decor spots (ones already on display stay where they are).'] },
  { v: '0.78', at: '2026-10-25 19:50', notes: ['Weekly challenge medals now record the week’s theme: Menu → Medals shows the theme (like Pantry Week) and its special rule under each medal, and so do the medal’s own panel and the win screen.'] },
  { v: '0.77', at: '2026-10-25 19:30', notes: ['Weekly challenge medals now show up without restarting the game: opening Menu → Medals checks for new ones, and a game left open over the end of the week picks up the medals just awarded. Before, they only appeared after reloading.'] },
  { v: '0.76', at: '2026-10-25 13:20', notes: ['On phones, the little Goal / Contract button (when you minimize the goal card) now sits under your gold counter instead of in the top bar.', 'New setting: Settings → Top of the screen → “Show players online and unique visitors” brings the two counters back beside the Menu button on phones (they’re always shown on computers, and are also in the Info panel).'] },
  { v: '0.75', at: '2026-10-25 12:50', notes: ['Tap a fully grown crop and your farmer goes straight to harvest it. No need to open the plot’s menu and press Harvest first (if your storage is full you’ll be told instead).'] },
  { v: '0.74', at: '2026-10-25 12:30', notes: ['Roomier phone screen: on phones the Activity, Updates and Daily Puzzle buttons now live in one “Info” button at the bottom left, which also shows the weather forecast and the visitor and online counts. The top bar is less crowded, fair-weather tags are hidden, and the bottom buttons no longer overlap on small phones.'] },
  { v: '0.73', at: '2026-10-24 23:45', notes: ['Send feedback: share ideas, report bugs or say anything at all, straight to the developer. Find it in Menu → Game → Send feedback, or tap the speech-bubble button (top right on computers, bottom right on phones). If you’re offline it’s saved and sent next time you connect.'] },
  { v: '0.72', at: '2026-10-24 16:30', notes: ['Six new Discoveries to spend your tokens on (45 in all): Orchard Grove (pear, cherry and plum trees), Market Garden (corn, onions, peppers and cabbage), Gourmet Kitchen (pizza, quiche, jam tarts, fish pie and harvest roast), Brewery (a new Brewhouse station, hops, ale, stout and cherry ale), Cheese Cave (aged cheddar, blue cheese and smoked cheese) and Jeweler (rough gems from Iron Seams, cut into rings, necklaces and a jewel box for your house).', 'The new crops have their own seasons, count toward Mastery, and onions, cabbage and pear trees are hardy enough for snow days.'] },
  { v: '0.71', at: '2026-10-23 18:50', notes: ['Tapping a farm plot when you have no seeds now reminds you to buy some at the Open Market, and the plot’s menu has a “Show me the market” link that jumps there.'] },
  { v: '0.70', at: '2026-10-23 17:40', notes: ['New players now start their first farm in the Online Valley: pick a name (if it’s taken you’ll be offered the next free one) and play the tutorial from there. You can make the farm private any time in Menu → Settings. If the valley can’t be reached, you can start without a name and lock one in later.', 'A new counter beside the online count (a little person with a gold dot) shows how many different players have ever visited Harvest Valley.'] },
  { v: '0.69', at: '2026-10-23 17:10', notes: ['Buying now swaps only the button you pressed (×1 or ×5) for Cancel, not both. A quick second tap on that spot no longer cancels the purchase you just made.'] },
  { v: '0.68', at: '2026-10-23 16:40', notes: ['Panel action buttons now turn into a red × Cancel button in the same spot as soon as the action is queued or under way, instead of a separate × beside them.'] },
  { v: '0.67', at: '2026-10-23 12:50', notes: ['You can now set auto-sell keep amounts in Storage even while Auto-sell is switched off. Nothing sells until you turn it on, and your settings are kept.', 'When an action in a panel is already waiting in your farmer’s queue or being worked on, a red × button appears beside it so you can cancel it right there.'] },
  { v: '0.66', at: '2026-10-22 13:30', notes: ['New Manual (Menu → Game → Manual): search every good, building, upgrade, discovery and kind of land, with what it does, what it costs and where to find it. Pick a group to browse, or open a few “How it works” pages on quality, orders, mastery, seasons and more.', 'You can now move your house. After Rollers & Skids, select it and choose Pick a new spot; the tiles it would cover light up green (or red if something is in the way). It keeps everything on display and costs more the bigger it is.'] },
  { v: '0.65', at: '2026-10-22 12:30', notes: ['Your own house! Unlock Homemaking (Discovery → Home & decor, after the Brick Kiln and Fishing), then select empty grass you own and build a Cottage. Select the house to put decor on display. Pieces on display leave your storage, and you can store them again any time.', 'New station: the Carpenter’s Bench (Open Market → Stations) makes Wooden Chairs, Farmhouse Tables and Fish Trophies, and later Bookshelves and Painted Pictures. The Loom also weaves Woven Rugs and Curtains, the Potter’s Wheel makes Flower Vases and the Glass Furnace makes Oil Lamps. The market buys spare decor.', 'House Additions (after Land Surveying) grows your house a size at a time onto free grass beside it: House (1×2), Farmhouse (2×2) and Manor (2×3), each with more display spots. Pick which way it grows; the new tiles light up before you build, and if something is in the way the house tells you what.'] },
  { v: '0.64', at: '2026-10-22 12:00', notes: ['Race codes are now farm words, like WHEAT or BARN, so they are easy to say and share. Races you already started with the old codes still work.'] },
  { v: '0.63', at: '2026-10-22 10:30', notes: ['New Discovery: Salvage (Upgrades, after Rollers & Skids). Select a station, storage building or sprinkler you have a duplicate of and press “Take it down”: half of the gold and materials it cost, upgrades included, come back to you. The building must be empty, and your storage must still hold everything afterwards.', 'Discovery is now scarcer: Legend and Mythic mastery pay gold (20,000g and 100,000g) instead of Discovery, and Grand orders no longer give Discovery (they still pay big gold and score). Discovery you already have is untouched.'] },
  { v: '0.62.1', at: '2026-10-22 09:30', notes: ['The Daily Puzzle no longer pays Discovery. Finishing it now pays a gold bonus (half of what the steps paid, less if you named an answer or guessed wrong three times) and a bigger one every 7th day in a row. Discovery now comes only from things you do and build.'] },
  { v: '0.62', at: '2026-10-21 18:00', notes: ['Grand orders: when you complete or pass one, the next one comes an hour later, and the game tells you so. They now arrive by the real clock, so one can be waiting when you come back.', 'Farmhand: new switch “Buy seeds when they run out” (Menu → Farmhands, or select the Homestead). When a plot they tend is ready to plant and there is no seed in storage, they buy a few at the market price from your gold, so a Tend plot job can till, plant, water and harvest again and again on its own.'] },
  { v: '0.61.2', at: '2026-10-21 17:30', notes: ['The Activity, Updates and Puzzle buttons now sit along the bottom edge of the screen on computers too (they were halfway up the left side), and their drop-down lists open upward from there.'] },
  { v: '0.61.1', at: '2026-10-21 15:00', notes: ['Daily Puzzle clues now say what the answer is like in the real world, as well as where it comes from. For example a crate “could carry or store things”, so you’re not only told which station to use.'] },
  { v: '0.61', at: '2026-10-21 14:00', notes: ['The Order Board grows: it starts with 3 requests and gains one more for every 14 Discoveries you unlock, up to 6.', 'New Discovery for veteran farmers: Grand Orders (Upgrades, after Granary and Master Crafting). The Order Board then posts Grand orders that ask for five different goods, many of each, scaled to how big your storage is, and pay big gold, score and Discovery (the first 3 Discovery rewards each day).', 'Weekly challenge: the “someone passed you” notice now only appears when someone takes #1 from you.'] },
  { v: '0.60', at: '2026-10-21 06:00', notes: ['Weekly challenge: you now get a small notice the first time someone passes your score. If you win your place back and are passed again, you get one more. Turn it off in Menu → Settings → Notifications.'] },
  { v: '0.59', at: '2026-10-20 17:20', notes: ['Sprinklers can now be picked up. Select a Sprinkler or Deluxe Sprinkler and press “Pick up”: it’s free, and the kit goes back into storage, ready to place somewhere else. Storage needs a free slot. Placing a picked-up kit again earns no extra build score.'] },
  { v: '0.58.3', at: '2026-10-20 17:00', notes: ['Daily Puzzle: when the next step is made from the good you just handed in, you now keep those goods instead of having to make them again. A message tells you when this happens.'] },
  { v: '0.58.2', at: '2026-10-20 16:45', notes: ['Station recipes now show how many of the finished good you already have, in white brackets after it, so you can see at a glance what you’re running low on.'] },
  { v: '0.58.1', at: '2026-10-20 16:30', notes: ['Daily Puzzle hints now cost much more: about 8% of your gold for the first hint and 15% for the second (never more than a quarter of your gold). Hints used to be a rounding error, so solving the puzzle yourself is now worth more.'] },
  { v: '0.58', at: '2026-10-20 16:30', notes: ['Menu → Game: Spread the word now opens a small box with “Enjoying the game? Share it for free with a friend.”, the game’s address you can select, and a Copy button. The website button now opens the Zero Crunch website.'] },
  { v: '0.57.1', backend: true, at: '2026-10-20 15:15', notes: ['Spread the word and the website button now use zerocrunch.ca/harvest-valley.'] },
  { v: '0.57', at: '2026-10-20 15:30', notes: ['Menu → Game has two new buttons: Spread the word shares Harvest Valley with friends (or copies the link if sharing isn’t available), and Harvest Valley website opens the game’s home page.'] },
  { v: '0.56', at: '2026-10-20 12:30', notes: ['New storage buildings, each unlocked in Discovery → Upgrades: the Silo holds crops, the Cold Cellar holds eggs, milk and everything cooked, baked, preserved or brewed, and the Material Yard holds logs, stone, ore, clay, wool and building parts. Goods fill their own building first and only the rest takes space in main storage. Buy the kits at the Open Market → Stations (one of each per area). Select one to expand it, up to four times.', 'Auto-sell: turn it on in Storage (or Settings → Selling), then tap a good’s “Auto-sell off” button to choose how many to keep: Sell all, or keep 10, 50, 100, 250, 500 or 1,000. Anything above that sells at the market by itself, lowest quality first. Goods you haven’t set are never sold.', 'The main menu is tidier: it is grouped into Your farm, Play together, Save and backup, Game and Controls. Tap a heading to fold or unfold it; the game remembers your choice.'] },
  { v: '0.55.1', backend: true, at: '2026-10-20 12:00', notes: ['The shared market keeps only the last 7 days of trade history, trimmed once a day.'] },
  { v: '0.55', at: '2026-10-20 09:45', notes: ['New setting: “Pause the game when storage is full” (Menu → Settings → Pausing). Turn it on and the game holds still, with a banner, whenever storage is full. It carries on by itself as soon as you sell, use or give away something, or upgrade storage. It is off by default and never applies in races or weekly challenges.', 'Your farmhand can now use fertilizer. In Menu → Farmhands, switch on “Use fertilizer on the plots they tend”. They then fertilize each crop they plant, and any growing crop that has none, one Fertilizer per plot from storage. When storage has none left they carry on without it. It is off by default so your stock is not used up by surprise.'] },
  { v: '0.54', at: '2026-10-19 13:00', notes: ['The Daily Puzzle now has its own button on the main screen, next to Activity and Updates. It shows which step you are on (like “Puzzle 2/4”), and a red dot when a fresh puzzle is waiting. Tap it to drop down today’s clue, buy a hint, hand in an answer, and see your streak and time left, without opening the menu. It shows a tick once you have solved today’s.'] },
  { v: '0.53.2', at: '2026-10-19 12:30', notes: ['Fixed: menus no longer jump back to the top while you are scrolling. Storage, the main menu, Mastery, station recipe lists and every other long menu stay where you left them when a number changes, so you can pick things further down the list (like a recipe) without chasing it.'] },
  { v: '0.53.1', at: '2026-10-19 12:00', notes: ['Daily Puzzle hints now cost a share of the gold you hold (1% for a hint, 3% to name the answer) when that is more than the usual price, so they always mean something, however rich your farm is.'] },
  { v: '0.53', at: '2026-10-19 12:00', notes: ['New: the Daily Puzzle (Menu → Daily Puzzle). Every day brings a riddle chain of 3 to 5 steps. Work out which good the riddle describes, make it, and hand it in; each answer reveals the next clue, which usually leads on from what you just made: what it goes into, what it comes from, or what else the same station makes. Every clue fits exactly one good your farm can make today.', 'Each step pays gold, and finishing gives up to 3 Discovery, plus 3 more for every 7 days in a row. Stuck? Buy a hint, or have the answer named. Wrong guesses take nothing, but three or more lower the Discovery reward. A new puzzle arrives at 00:00 UTC. It opens after the tutorial and is off during races and weekly challenges.'] },
  { v: '0.52', at: '2026-10-18 17:45', notes: ['Phones: the tile menu at the bottom is much shorter. It now shows just the name, the key numbers and the main buttons, and leaves the long descriptions and tips folded away. Tap “More” at the top of the menu to see everything, “Less” to fold it back. Lists like stations, the market and your home still open full.'] },
  { v: '0.51', at: '2026-10-18 09:30', notes: ['The Valley Green can now move onto a corner area you have already surveyed, as long as nothing is built on it. Open the Valley Green or the Monument Depot, pick the corner, and tap again to confirm: that empty area is replaced by the Green, and the old spot goes back to unsurveyed land. Corners with buildings stay locked, and the button now says why.'] },
  { v: '0.50', at: '2026-10-17 15:30', notes: ['Mastery has two new tiers above Master: Legend and Mythic. Legend sells for 25% more, speeds that good up by 20% and gives an extra on every second harvest or batch; Mythic goes to 30% and 25%. They are a long way off. Goods you have already mastered keep their perks and will earn Legend when you next make one. Open Mastery from the menu to see your progress.'] },
  { v: '0.49.1', backend: true, at: '2026-10-17 14:30', notes: ['Sales and purchases are reported to the shared market in batches instead of one request each.'] },
  { v: '0.49', backend: true, at: '2026-10-17 14:00', notes: ['Lighter market traffic: one small request every 90 seconds instead of two every 30, and the trade ticker only loads while it is open.'] },
  { v: '0.48.2', at: '2026-10-17 13:10', notes: ['Monument Auto-give now switches itself off when you reach the day’s limit, and tells you so with a message (your allowance resets at 00:00 UTC; turn Auto back on then).'] },
  { v: '0.48.1', at: '2026-10-17 12:40', notes: ['Fixed: Auto-give for the monument could stall. If your goods ran out, a new day’s allowance started, or the monument moved to a phase that wants something new, it kept waiting on old information. It now checks again about once a minute and carries on by itself as soon as there’s something to give.'] },
  { v: '0.48', at: '2026-10-17 12:00', notes: ['Valley Monument: every good the monument wants now has an Auto button. Turn it on and that good goes to the monument by itself, a batch every 20 seconds or so while the game is open, until your allowance for the day is used. It gives every one you have, so leave it off for goods you need yourself.', 'Builder’s days: on any day you give to the monument, your quarries, clay banks, iron seams, woods, reeds, wildflowers and ponds refill twice as fast, and digging doesn’t wear deposits down, so you won’t run out of stone while you build. It lasts until 00:00 UTC; the monument screen and each deposit say when it’s on.'] },
  { v: '0.47', at: '2026-10-17 11:20', notes: ['Five new discoveries for seasoned farms. Fruit Wines: the Cider Press makes Berry Wine (berry juice and honey) and Apple Brandy (cider over charcoal). Glassworks: every catch from a pond also brings up sand; melt it into glass at the new Glass Furnace, then blow Glass Jars or make Stained Glass with dye. Seed Saving: every third harvest gives you a seed back. Cold Frames (after Glassworks): tender crops grow like hardy ones, untouched by frost and winter, and can be planted on snow days. Granary: every Homestead storage level past the first five holds 100 instead of 60, including levels you already have.', 'Two new contracts on the Order Board use the new goods: The Vintner’s Cellar and the Glassblower’s Fair.'] },
  { v: '0.46', at: '2026-10-17 10:30', notes: ['New: Mastery. Every crop (carrots, wheat, pumpkins and the rest) and every animal good (eggs, milk, wool, honey, mushrooms) now counts how many you’ve produced on your farm. Reach Bronze, Silver, Gold and finally Master to give that good its own perks: it sells for up to 20% more, grows or is made up to 15% faster, and from Gold some harvests and batches give one extra. Each tier also gives Discovery.', 'Find it in Menu → Mastery. An item’s info card shows its progress, and storage shows a badge for each mastered good. Only what you harvest or collect counts (not buying or trading), and cheaper goods need more to reach each tier. Counting starts now for every farm.', 'Mastery is switched off in races and weekly challenges, so every run stays fair.'] },
  { v: '0.45.1', at: '2026-10-16 20:05', notes: ['Menus now open on top of everything: the progress meters, tips, warning bars and side panels no longer show through or sit over the main menu while it is open.'] },
  { v: '0.45', at: '2026-10-16 19:50', notes: ['On a phone, the race and weekly challenge progress is now a small vertical meter on the left instead of a wide bar across the top, so it no longer covers the map. Races get one column per racer (yours is gold), filling upward; the time sits above and your score below. Tap the meter any time for the full standings. On a computer nothing changes.'] },
  { v: '0.44', at: '2026-10-16 18:30', notes: ['Easier to play on a phone: buttons, tabs and the goal card’s controls are now big enough for a thumb (44 pixels), and on a phone the valley market ticker starts hidden so the map has more room. Turn it back on in Settings → “Show the valley market ticker at the top”. Farms that already had the ticker showing keep it.'] },
  { v: '0.43', at: '2026-10-16 15:40', notes: ['Storage can now be sorted. Open Storage and pick Sort by: Category (the usual headings), A–Z, Most, Fewest, Worth (highest total value first, so you can see what’s worth selling), Best quality, or Newest. The category tabs still filter the list, and your choice is remembered.'] },
  { v: '0.42.4', at: '2026-10-16 14:55', notes: ['Valley Monument: if you have less than one item’s worth of today’s allowance left, you can now still give one last item and go a little over, instead of being stuck with goods that are worth too much. The monument’s help card explains it.'] },
  { v: '0.42.3', at: '2026-10-16 11:00', notes: ['The Valley Green now sits against a corner of your farm instead of beside a side, so it never gets in the way of surveying. You can move it to any corner you haven’t built on: select the Monument Depot or the Green and pick a corner. Moving is free, and the area it leaves becomes open land you can survey.'] },
  { v: '0.42.2', at: '2026-10-16 10:05', notes: ['The Fence Kit is now the Land Kit, since you need it for more than fences: expanding your land (from the 9th tile), surveying new areas and building a Sheep Pasture. Your existing kits carry over. When you’re short of Land Kits, the message now tells you where to make them: at the Workbench, from planks and stone.'] },
  { v: '0.42.1', at: '2026-10-16 09:40', notes: ['Starting your first Online Valley farm now asks for your name and locks it to you, so no one else in the valley can use it. It shows on the leaderboard, in the weekly challenge and on your medals. If it’s taken, you’ll get the next free number (Sam1, Sam2…).'] },
  { v: '0.42', at: '2026-10-15 23:45', notes: ['Valley Monuments! Every online farm now builds one shared monument together, and the first is The Great Pyramid, with two weeks to build it. It rises through four stages (foundation, body, detail and the gold capstone), and each phase asks for different goods: stone and bricks, then timber, then food and crafts, then fine goods.', 'Once you finish the tutorial, a Valley Green opens beside your land: a paved plaza with the pyramid at full size and a Monument Depot, where you give goods from storage. It never costs you land and doesn’t count toward your building limits. The new pyramid button by the map controls takes you there, and you can also give from the Homestead or Menu → Valley Monument.', 'Finer goods count for more points, and you can give up to 800 points a day, so every farm gets a share of the work. Giving earns no gold. Instead you earn a small model of the pyramid for your farm (it shows the current stage), +1 Discovery for your first gift in each phase, and +2 when it’s finished. Each stage the valley reaches gets a little celebration. Tap “How do monuments work?” in the Depot for the full rules.', 'The Homestead now has a Notices list for things that are easy to miss, like goods the monument needs or a storage upgrade you can afford. A gold “!” over the Homestead means something new is waiting.'] },
  { v: '0.41', at: '2026-10-15 15:40', notes: ['Seasons and weather! The year now runs through Spring, Summer, Autumn and Winter, seven days each, so every season lines up with a weekly report. The day in the top bar shows the season and today’s weather; tap it for the forecast, what’s in season and the year at a glance.', 'Each season favours its own crops: they grow 25% faster and sell for 20% more, along with seasonal goods like berry juice in summer, pumpkin pie in autumn and wool blankets in winter. The market’s pick of the day is often something in season.', 'Gentle weather, never storms: rain waters every growing crop while it falls (it counts for quality), sunny spells speed growth a little, summer heat dries soil out so crops need water sooner, mist and fog are just for looks, frosty mornings slow tender crops until 10:00, and on snow days only hardy crops (carrots, potatoes, wheat and apple trees) can be planted. In winter, tender crops grow a little slower.', 'The valley changes with the seasons: blossom in spring, deep greens in summer, golden leaves in autumn, frost and snow-capped roofs in winter, with rain, snowflakes, mist and drifting leaves. Each season has its own music, and the ambience brings rain, summer cicadas and quieter winter days.', 'Races and weekly challenges stay on a fair spring day with no weather, so every run is the same for everyone.'] },
  { v: '0.40', at: '2026-10-15 14:45', notes: ['Stone, clay and iron ore now run out. Each Boulder Field, Clay Bank and Iron Seam holds a deposit (about 60 stone, 60 clay or 30 ore); select one to see how much is left. Surface rocks still come back a few at a time until the deposit is used up.', 'Every tile you already own starts with a full deposit. When one is worked out you can change the land, buy from the market, survey new areas for fresh deposits, or unlock Deep Quarrying (after Prospecting) to reopen it.', 'Trees, ponds, flowers and reeds keep regrowing as before. Races and weekly challenges are unchanged.'] },
  { v: '0.39.3', at: '2026-10-15 13:20', notes: ['Balance: a station’s Quality upgrade now lifts goods one tier above their ingredients, never more. Basic logs make Good planks; Excellent goods need Good ingredients (well-watered or fertilized crops) plus the upgrade. Goods you already have keep their quality.', 'Master Crafting’s second Quality level now gives a bonus item on every third batch at that station instead.'] },
  { v: '0.39.2', at: '2026-10-15 08:20', notes: ['Repeat can now stop on its own: when Repeat is on, pick how many times (1 to 50, or Forever) from the box beside it. It shows how many are done and turns itself off at the end.', 'Four new Weekly Challenge themes join the rotation from next week: Barnyard Week (coop and dairy), Woolly Week (sheep and loom), Creamery Week (butter and cheese) and Helping Hands Week (a farmhand who runs errands). This week’s challenge is unchanged.'] },
  { v: '0.39.1', at: '2026-10-15 09:00', notes: ['Animal feed now always pays off: eggs, milk and wool are worth more than the crops they eat (milk is worth a little more, and carrot and vegetable feeds give more).', 'Orders no longer ask for Good-quality goods you can’t make yet (like Good logs or stone). They only ask for Good when your crops or a tuned station can make it.', 'You can now buy a Stove kit to build a second Stove once you have a second area.', 'Stations on Repeat now say when they use things up: Storage and the item card show “used automatically by …”, and the Activity log notes it once a day.'] },
  { v: '0.39', at: '2026-10-15 08:30', notes: ['Animals! Once you survey your first new area, a new Animals branch opens in Discovery: Chickens, Dairy Cows, Sheep and a Creamery. All peaceful.', 'Hens lay eggs and cows give milk when you feed them spare wheat or vegetables; sheep grow wool. Better feed makes better eggs, milk and wool.', 'New goods: omelettes and custard at the Stove, butter and cheese at the Creamery, Farmhouse Cake in the Oven, yarn and wool blankets at the Loom. Three new contracts to go with them.'] },
  { v: '0.38.1', at: '2026-10-15 07:50', notes: ['New-land contracts no longer hold you up: if the next contract needs an area you haven’t surveyed yet (like a Meadow for wildflowers), a contract for land you already have comes first, and the other waits until you survey its area.', 'Fixed: surveying a fourth area could ask for roof tiles before you owned Clay Banks to make them. Roof tiles are now only asked for once you have Clay Banks.'] },
  { v: '0.38', at: '2026-10-14 16:15', notes: ['Click any recipe at a station to see each ingredient: how many you have, how many you need, and what it costs at the market.', 'New Discovery: Errands (after Farmhand). From that recipe view, press Send farmhand shopping: your farmhand walks to the Open Market, buys what’s missing, brings it back and loads the station (one batch or fill every free slot), then goes back to their usual jobs.'] },
  { v: '0.37.2', at: '2026-10-14 15:50', notes: ['How quality works is now explained in the game: Storage → “How do I make Good and Excellent goods?”, a line on every farm plot and station (with “More about quality”), and on right-click item cards. Your first Basic harvest also gives a short tip.', 'In short: water a crop at both growth stages for Good, add fertilizer too for Excellent. Station goods are as good as their lowest ingredient, plus the station’s Quality upgrade.'] },
  { v: '0.37.1', at: '2026-10-14 15:10', notes: ['Right-click any item, recipe, kit or market row to see what it is: what it does, where it comes from, what it’s used to make and what it’s worth. Works in Storage, the market, stations and orders. On touch screens, press and hold.'] },
  { v: '0.37', at: '2026-10-14 14:05', notes: ['On a computer, the action menu now works like a window: drag its title bar to move it, drag any edge or corner to resize it, and it opens in that spot from then on. Double-click the title bar to send it back beside the tile you pick.', 'Weekly challenge runs are 10 minutes from next week (this week stays at 15 minutes, so everyone already on the board plays the same run).', 'The live count at the top right is now just the green dot and the number.'] },
  { v: '0.36.5', at: '2026-10-14 13:45', notes: ['On a computer, right-click the action menu and choose Move and resize: drag it anywhere, drag the corner to resize, then Done. It opens in that spot from then on. Right-click it again to go back to opening beside the tile.'] },
  { v: '0.36.4', at: '2026-10-14 13:30', notes: ['The action panel now sits a little further from the tile you pick, so it covers less of the buildings around it.'] },
  { v: '0.36.3', at: '2026-10-14 13:40', notes: ['On computers and tablets, the action panel now opens beside the tile you pick and follows it as you move the view (phones keep the panel at the bottom).', 'Every action you can take now has a gold border, so no single option looks like the only one. Greyed-out actions still say what they need.'] },
  { v: '0.36.2', at: '2026-10-14 13:30', notes: ['A live count at the top right shows how many copies of Harvest Valley are open right now, updated every 30 seconds.'] },
  { v: '0.36.1', at: '2026-10-14 09:40', notes: ['Your player name now lives with you, not a farm: set it on the Weekly challenge screen or in Settings → Your player name (private farms too). It shows on the leaderboard, the weekly board and your medals instead of “Farmer”.'] },
  { v: '0.36', at: '2026-10-14 01:30', notes: ['New: the Weekly Challenge (main menu). Everyone gets the same head start for the week, with a new theme each week: Bumper Crop, Baker’s, Fisher’s, Timber, Quarry and more, each with its own starting buildings, land and score bonus.', 'One ranked 15-minute run a day; your best run of the week counts. Extra runs are practice. The top three each week win a gold, silver or bronze medal.', 'Medals live in Menu → Medals and can be put on show on any of your farms. Select a medal on your farm to see when you won it.', 'New: a player key (Menu → Player key). One code that carries your locked name, your medals and your backed-up farms to another phone or computer. Restoring a farm now lets you pick which of your three slots it goes into.'] },
  { v: '0.35.1', at: '2026-10-13 23:40', notes: ['The game is now called Harvest Valley, with new title art. Your farms, saves and backup codes carry on as before.'] },
  { v: '0.35', at: '2026-10-13 23:20', notes: ['Three ways to play from the main menu: Online Valley (shared market prices, the ticker and the leaderboard), Private farm (just you, on your own time) and Race.', 'Your existing farms are Online Valley farms. Settings → This farm can make a farm private (one way only).'] },
  { v: '0.34.1', at: '2026-10-13 23:10', notes: ['Buying land (and surveying new areas) now lists everything it costs, not just the gold, with how much of each you have and how many more you need.'] },
  { v: '0.34', at: '2026-10-13 23:00', notes: ['Open Market → Stations now shows only what you can build. Stations you’ve reached your limit on have their own “At your limit” list.', 'New Farmhands menu (Menu, the Jobs button on the farmhand bar, or the Homestead): pause, set speed, and reorder, remove or clear jobs in one place.'] },
  { v: '0.33.1', at: '2026-10-13 22:40', notes: ['Every race now starts differently: gold, land, stations, plots, seeds and even spare Discovery are shuffled, but everyone in the same race gets the identical head start, and it’s always winnable.', 'Watch out for greed traps: a race-day bargain on a station you can’t actually use, and a rich-looking special request that pays gold but hardly any points.'] },
  { v: '0.33', at: '2026-10-13 22:30', notes: ['Save slots: keep up to three farms side by side. Main menu → Your farms (or Menu → Your farms) to switch farms or start a new one.', 'Race with friends: host a race to 500, 1,000, 2,500 or 5,000 points and share the code or invite link. Everyone starts the same head-start farm in its own slot, so your real farm is safe. A live race bar shows everyone’s progress, and first to the target wins. No pausing during a race, and races don’t affect valley prices or the leaderboard.'] },
  { v: '0.32.1', at: '2026-10-13 22:00', notes: ['Idle pause now offers Never, 5, 10, 15 or 30 seconds, or 2 minutes (Settings → Pausing). It starts at 2 minutes.'] },
  { v: '0.32', at: '2026-10-13 21:55', notes: ['The game now pauses itself if you haven’t done anything for a while (10 minutes to start). Pick Never, 2, 5, 10 or 30 minutes in Settings → Pausing. Any tap, click or key carries on.', 'Menu → Cloud backup has a clear Copy code button next to your backup code.'] },
  { v: '0.31.1', at: '2026-10-13 21:45', notes: ['The Open Market’s Buy tab now warns you when storage is full (or nearly full), before you try to buy.'] },
  { v: '0.31', at: '2026-10-13 21:40', notes: ['Cloud backup: Menu → Cloud backup saves your farm to the valley and gives you a 12-letter code. On any phone or computer, choose Restore from a backup code on the main menu to get your farm back. It backs up on its own every 10 minutes or so while you play.', 'On phones, Share save file opens your phone’s share sheet so you can save the file to Files, AirDrop it or email it.'] },
  { v: '0.30.1', at: '2026-10-13 15:30', notes: ['Settings → Leaderboard name: lock in a name that’s yours alone across the valley. If it’s taken you’ll be offered the next free number, like Zac1. Locked names show a ✓ on the leaderboard.'] },
  { v: '0.30', at: '2026-10-13 15:15', notes: ['Valley leaderboard: see how your farm compares with everyone else’s, by top score and by best pace (score per day played, for farms at least 7 days old). Open it from the Menu or from your weekly report.', 'Your farmer’s name is shown by default; turn that off in Settings to appear as “A farmer”. The leaderboard works on the web version.'] },
  { v: '0.29', at: '2026-10-13 15:00', notes: ['Every 7 days a weekly report shows how your farm did: gold, score, Discovery, sales, harvests, orders and what you made. Turn it off from the report or in Settings.', 'Settings now has its own page in the Menu, with Pausing, Notifications and Sound.'] },
  { v: '0.28', at: '2026-10-13 14:45', notes: ['Hit rock bottom (no gold for seeds, nothing to sell, nothing growing and no work that brings in goods) and the valley bank lends you 100g, once. Pay it back: it comes out automatically at 200g, or tap Loan in the top bar.', 'Get stuck again before repaying it, and that farm is over: start a new one or take one last look around.'] },
  { v: '0.27.3', at: '2026-10-13 14:30', notes: ['On computers, the valley market ticker now stretches across the full width of the screen.'] },
  { v: '0.27.2', at: '2026-10-13 14:20', notes: ['Discovery, Storage and the Market remember the category tab you last picked, even after you reload the game.'] },
  { v: '0.27.1', at: '2026-10-13 14:10', notes: ['On computers, the valley market ticker now runs along its own row under your gold and storage, so it’s easier to read.'] },
  { v: '0.27', at: '2026-10-13 14:00', notes: ['Harvestworks has sound! Gentle chimes when crops ripen, stations finish and contracts complete, soft sounds for chopping, mining, fishing, watering and selling, plus a breeze, birds by day and crickets at dusk.', 'Optional calm background music that never repeats itself.', 'Menu → Sound: turn sound on or off, and set Effects, Ambience and Music volumes. Press M to mute quickly.'] },
  { v: '0.26', at: '2026-10-13 13:45', notes: ['New in Menu → Options: choose whether the game pauses when you switch to another tab or app. Turn pausing off and your farm keeps working while you’re away (up to 2 hours), catching up when you come back.'] },
  { v: '0.25', at: '2026-10-13 13:30', notes: ['New lands: unlock Land Surveying in Discovery, then select a dashed area past your map’s edge to survey it. Each area is a Meadow, Clay Banks, Marsh or Iron Hills, and every survey costs more than the last.', 'New resources in those areas: wildflowers, clay, reeds and iron ore, with new things to make: Wildflower Honey, Dye and Dyed Cloth (Dye Vat), Roof Tiles and Clay Pots (Potter’s Wheel), Baskets, and Iron Ingots and Iron Tools (Forge). Five new contracts use them.', 'Building limits: you can build one of each station per area you own, and two Storage Barns. Buildings you already have stay. Surveying new land raises the limit.', 'Rollers & Skids (Discovery): move a station, storage building or sprinkler to a new spot, upgrades and all. It’s pricey, and each move costs more for a few days.'] },
  { v: '0.24', at: '2026-10-13 11:45', notes: ['New title art on the welcome screen and main menu.'] },
  { v: '0.23.1', at: '2026-10-13 11:30', notes: ['Fixed: the “new version” banner could keep asking you to reload without actually loading the update. Reload now always brings in the latest version, and Later stops it asking again for that update.', 'The banner can now be reached from the title screen too.'] },
  { v: '0.23', at: '2026-10-13 11:15', notes: ['Buildings no longer fade when they’re in front of things; the shorter buildings keep the view clear.', 'The eye button (or X) now shows the name of every building on your farm.'] },
  { v: '0.22', at: '2026-10-13 11:00', notes: ['Buildings are about 25% shorter, so a busy farm is easier to see across. Each one keeps its look: chimneys, sails, awnings and all.', 'Busy farms are easier to read.'] },
  { v: '0.21', at: '2026-10-13 10:45', notes: ['Buildings, trees and rocks now fade when they stand in front of your farmer, your farmhand, the tile you’ve selected or the tile under your mouse, so nothing gets lost behind them.'] },
  { v: '0.20.2', backend: true, at: '2026-10-13 10:30', notes: ['Show your support now points to Ko-fi (ko-fi.com/zerocrunchgames) instead of PayPal, with a new QR code.'] },
  { v: '0.20.1', backend: true, at: '2026-10-13 10:20', notes: ['Name back to Harvestworks. Show your support opens its own screen with a big QR code and an Open PayPal link (title menu and Menu).'] },
  { v: '0.20', at: '2026-10-13 10:10', notes: ['New title screen and main menu: Continue, New farm (name your farmer) and Load a save file.', 'New players can take a quick hands-on tutorial; replay it any time from the Menu.'] },
  { v: '0.19.1', at: '2026-10-13 00:20', notes: ['Open Market → Buy has category filters, the same as Sell.'] },
  { v: '0.19', at: '2026-10-13 00:15', notes: ['Open Market → Buy now sells every good you’ve made at least once (apples, bread, cider and the rest), at about 1.75× its normal value, Normal quality.', 'On the web version, buying pushes that good’s shared price up and selling pushes it down, for everyone.'] },
  { v: '0.18.1', at: '2026-10-13 00:05', notes: ['Fixed: choosing a save file in Menu → Load a save file did nothing. You now get a “Reading…” note, then a “Load this farm” button (or a clear error if the file isn’t a save).'] },
  { v: '0.18', at: '2026-10-12 23:42', notes: ['Menu → Download save file saves your whole farm as a .json file; Load a save file brings it back on any device or on the web version.', 'Save codes are still there under “Or copy and paste a save code instead”.'] },
  { v: '0.17', at: '2026-10-12 23:40', notes: ['Move your farm: Menu → Export save code gives you a code to copy; Menu → Import a save code on another device or on the web version brings the whole farm across.'] },
  { v: '0.16', at: '2026-10-12 23:28', notes: ['The valley market now moves at the pace of the crowd: with only a couple of traders, prices take about a day to settle back; with dozens or hundreds, they settle in minutes and each sale has a smaller effect.', 'The market shows how many traders are active this hour and how long prices take to settle.'] },
  { v: '0.15', at: '2026-10-12 23:20', notes: ['Shared valley market: on the web version, every player’s sales and purchases move prices for everyone. Prices drift back to normal over a few hours, between half and 1.6× of normal.', 'The market shows each price’s movement (▲/▼) and whether shared prices are connected.', 'Valley market ticker in the top bar shows recent trades. Collapse it with –, and switch between Slow and Fast.'] },
  { v: '0.14', at: '2026-10-12 23:02', notes: ['Activity log: a list of everything you and your farmhand have done. Open it with the Activity button at the bottom left.', 'Updates log (this list): opens by itself after each update so you can see what changed.'] },
  { v: '0.13', at: '2026-10-12 22:58', notes: ['Fertilized crops grow 40% faster as well as gaining +1 quality.'] },
  { v: '0.12', at: '2026-10-12 22:56', notes: ['Add fertilizer to a crop that’s already growing.'] },
  { v: '0.11', at: '2026-10-12 22:54', notes: ['Sell seeds, seedlings, saplings and fertilizer at the market (half price).', 'Storage and the market explain how to use seeds, saplings, fertilizer and kits.', 'Apple Seedling renamed Apple Tree Seedling.'] },
  { v: '0.10.1', at: '2026-10-12 22:50', notes: ['No more blue flash when tapping the map on phones.'] },
  { v: '0.10', at: '2026-10-12 22:47', notes: ['The contract card lists what you need with have/need counts.', '“See everything it takes” shows a production tree back to raw materials.'] },
  { v: '0.9', at: '2026-10-12 22:42', notes: ['Clear all of the farmhand’s jobs from the status chip or the Homestead.'] },
  { v: '0.8.1', at: '2026-10-12 22:40', notes: ['Upgrade costs wrap instead of hiding under the button.'] },
  { v: '0.8', at: '2026-10-12 22:38', notes: ['Every station’s Capacity upgrades to 12 slots and Speed to ×5.0.', '“Fill ×N” loads as many batches as you can in one trip.'] },
  { v: '0.7', at: '2026-10-12 22:35', notes: ['Farmhand play/pause and speed (1×/2×/3×) buttons.'] },
  { v: '0.6', at: '2026-10-12 11:02', notes: ['Change this land: clear forest, boulders or ponds, or make woodland, ponds and rock fields.', 'A minimized contract sits in the top bar.'] },
  { v: '0.5', at: '2026-10-12 10:58', notes: ['Minimize the goal/contract card.'] },
  { v: '0.4', at: '2026-10-12 10:41', notes: ['Phone layout and touch controls (twist to turn, two-finger slide to tilt).'] },
  { v: '0.3', at: '2026-10-11 23:11', notes: ['Upgrade rows show their cost and what you’re short of.'] },
  { v: '0.2', at: '2026-10-11 22:58', notes: ['Storage keeps growing: Homestead levels past 220, Storage Barns and Warehouses.'] },
  { v: '0.1', at: '2026-10-11 22:49', notes: ['First public build.'] }
];
